mapper.select:
SELECT COUNT(*)
FROM NOTE_PINS
WHERE USER_ID = #{userId, jdbcType=NUMERIC}
  AND PROJ_ID = #{projId, jdbcType=NUMERIC}

mapper.delete:
DELETE FROM NOTE_PINS
WHERE USER_ID = #{userId, jdbcType=NUMERIC}
  AND PROJ_ID = #{projId, jdbcType=NUMERIC}
  AND NOTE_ID = #{noteId, jdbcType=NUMERIC}

mapper.select:
SELECT COUNT(*)
FROM NOTES n
LEFT JOIN PROJ_MEMBERS pm
  ON pm.PROJ_ID = n.PROJ_ID
 AND pm.USER_ID = #{userId, jdbcType=NUMERIC}
LEFT JOIN PROJECTS p
  ON p.PROJ_ID = n.PROJ_ID
WHERE n.NOTE_ID = #{noteId, jdbcType=NUMERIC}
  AND (
        n.USER_ID = #{userId, jdbcType=NUMERIC}
        OR p.LEADER_ID = #{userId, jdbcType=NUMERIC}
        OR UPPER(NVL(pm.PROJ_ROLE, 'MEMBER')) = 'ADMIN'
      )

mapper.delete:
DELETE FROM NOTE_REPLIES
WHERE REPLY_ID = #{replyId, jdbcType=NUMERIC}
  AND USER_ID = #{userId, jdbcType=NUMERIC}
